// Install DOMPurify using npm or include the script in your HTML
// npm install dompurify
// For HTML include, use the CDN host provided by cdnjs.com

// Clean HTML code using DOMPurify
function sanitizeUserInput(input) {
    if (typeof DOMPurify !== 'undefined') {
        return DOMPurify.sanitize(input);
